);
  logic [1:0] state;
  logic [5:0] mshr;
  logic [7:0] mshr_data;
  logic mshr_write;
  wire req_ready_init;
  wire resp_valid_init;
  wire [7:0] resp_data_init;
  wire mem_wb_init;
  wire [7:0] mem_wdata_init;
  wire mem_fill_init;
  wire [5:0] mem_addr_init;
  wire _t0;
  wire _t1;
  wire _t2;
  wire [7:0] _t3;
  wire _t4;
  wire [7:0] _t5;
  wire _t6;
  wire [5:0] _t7;
  wire _t8;
  wire [1:0] _t9;
  wire _t10;
  wire [1:0] _t11;
  wire [7:0] _t12;
  wire _t13;
  wire _t14;
  wire [1:0] _t15;
  wire [5:0] _t16;
  wire _t17;
  wire _t18;
  wire [1:0] _t19;
  wire _t20;
  wire [5:0] _t21;
  wire [7:0] _t22;
  wire _t23;
  wire [1:0] _t24;
  wire _t25;
  wire [1:0] _t26;
  wire [7:0] _t27;
  wire _t28;
  wire _t29;
  wire [1:0] _t30;
  wire [5:0] _t31;
  wire _t32;
  wire _t33;
  wire [1:0] _t34;
  logic [5:0] mem0 [0:3];
  logic [7:0] mem1 [0:3];
  assign req_ready_init = 1'h0;
  assign resp_valid_init = 1'h0;
  assign resp_data_init = 8'h0;
  assign mem_wb_init = 1'h0;
  assign mem_wdata_init = 8'h0;
  assign mem_fill_init = 1'h0;
  assign mem_addr_init = 6'h0;
  assign _t0 = 1'h1;
  assign _t1 = (_t0 ? (state == 2'h0) : req_ready_init);
  assign _t2 = (_t0 ? ((((state == 2'h0) & req_valid) & (mem0[req_addr[1:0]][5:5] & (mem0[req_addr[1:0]][3:0] == req_addr[5:2]))) & (~req_write)) : resp_valid_init);
  assign _t3 = (_t0 ? mem1[req_addr[1:0]] : resp_data_init);
  assign _t4 = (_t0 ? ((state == 2'h1) & (mem0[mshr[1:0]][5:5] & mem0[mshr[1:0]][4:4])) : mem_wb_init);
  assign _t5 = (_t0 ? mem1[mshr[1:0]] : mem_wdata_init);
  assign _t6 = (_t0 ? (state == 2'h2) : mem_fill_init);
  assign _t7 = (_t0 ? ((state == 2'h1) ? {mem0[mshr[1:0]][3:0], mshr[1:0]} : mshr) : mem_addr_init);
  assign _t8 = ((state == 2'h2) & mem_rvalid);
  assign _t9 = (_t8 ? 2'h0 : state);
  assign _t10 = (_t8 ? 1'h1 : 1'h0);
  assign _t11 = mshr[1:0];
  assign _t12 = (mshr_write ? mshr_data : mem_rdata);
  assign _t13 = 1'h0;
  assign _t14 = (_t8 ? 1'h1 : 1'h0);
  assign _t15 = mshr[1:0];
  assign _t16 = {1'h1, mshr_write, mshr[5:2]};
  assign _t17 = 1'h0;
  assign _t18 = (_t9 == 2'h1);
  assign _t19 = (_t18 ? 2'h2 : _t9);
  assign _t20 = (_t1 & req_valid);
  assign _t21 = (_t20 ? ((mem0[req_addr[1:0]][5:5] & (mem0[req_addr[1:0]][3:0] == req_addr[5:2])) ? mshr : req_addr) : mshr);
  assign _t22 = (_t20 ? ((mem0[req_addr[1:0]][5:5] & (mem0[req_addr[1:0]][3:0] == req_addr[5:2])) ? mshr_data : req_data) : mshr_data);
  assign _t23 = (_t20 ? ((mem0[req_addr[1:0]][5:5] & (mem0[req_addr[1:0]][3:0] == req_addr[5:2])) ? mshr_write : req_write) : mshr_write);
  assign _t24 = (_t20 ? ((mem0[req_addr[1:0]][5:5] & (mem0[req_addr[1:0]][3:0] == req_addr[5:2])) ? _t19 : 2'h1) : _t19);
  assign _t25 = (_t20 ? ((mem0[req_addr[1:0]][5:5] & (mem0[req_addr[1:0]][3:0] == req_addr[5:2])) & req_write) : 1'h0);
  assign _t26 = req_addr[1:0];
  assign _t27 = req_data;
  assign _t28 = 1'h0;
  assign _t29 = (_t20 ? ((mem0[req_addr[1:0]][5:5] & (mem0[req_addr[1:0]][3:0] == req_addr[5:2])) & req_write) : 1'h0);
  assign _t30 = req_addr[1:0];
  assign _t31 = {2'h3, req_addr[5:2]};
  assign _t32 = 1'h0;
  assign _t33 = reset;
  assign _t34 = (_t33 ? 2'h0 : _t24);
  assign req_ready = _t1;
  assign resp_valid = _t2;
  assign resp_data = _t3;
  assign mem_wb = _t4;
  assign mem_wdata = _t5;
  assign mem_fill = _t6;
  assign mem_addr = _t7;
  always_ff @(posedge clk) begin
    if (rst) begin
      state <= 2'h0;
    end else begin
      state <= _t34;
    end
    if (rst) begin
      mshr <= 6'h0;
    end else begin
      mshr <= _t21;
    end
    if (rst) begin
      mshr_data <= 8'h0;
    end else begin
      mshr_data <= _t22;
    end
    if (rst) begin
      mshr_write <= 1'h0;
    end else begin
      mshr_write <= _t23;
    end
    if (_t14) begin
      mem0[_t15] <= _t16;
    end
    if (_t29) begin
      mem0[_t30] <= _t31;
    end
    if (_t10) begin
      mem1[_t11] <= _t12;
    end
    if (_t25) begin
      mem1[_t26] <= _t27;
    end
  end
endmodule

