  output wire [7:0] resp_data,
  output wire mem_wb,
  output wire [7:0] mem_wdata,
  output wire mem_fill,
  output wire [5:0] mem_addr
);
  logic [1:0] state;
  logic [5:0] mshr;
  logic [7:0] mshr_data;
  logic mshr_write;
  wire access_fire;
  wire [5:0] mshr_next;
  wire [7:0] mshr_data_next;
  wire mshr_write_next;
  wire [1:0] state_after_access;
  wire mem1_access_wen;
  wire [1:0] mem1_access_widx;
  wire [7:0] mem1_access_wdata;
  wire mem0_access_wen;
  wire [1:0] mem0_access_widx;
  wire [5:0] mem0_access_wdata;
  wire writeBack_fire;
  wire [1:0] state_after_writeBack;
  wire fill_fire;
  wire mem1_fill_wen;
  wire [1:0] mem1_fill_widx;
  wire [7:0] mem1_fill_wdata;
  wire mem0_fill_wen;
  wire [1:0] mem0_fill_widx;
  wire [5:0] mem0_fill_wdata;
  wire [1:0] state_next;
  wire state_w;
  wire [1:0] req_addr_1_0;
  wire [5:0] w;
  wire state_w_2;
  wire [1:0] mshr_1_0;
  wire [5:0] w_2;
  wire [1:0] mem1_access_widx_2;
  wire [5:0] mem1_access_widx_2_w;
  wire [3:0] req_addr_5_2;
  wire w_3;
  wire req_write_w;
  wire [1:0] mem1_fill_widx_2;
  logic [5:0] mem0 [0:3];
  logic [7:0] mem1 [0:3];
  assign state_w = (state == 2'h0);
  assign req_addr_1_0 = req_addr[1:0];
  assign w = mem0[req_addr_1_0];
  assign state_w_2 = (state == 2'h1);
  assign mshr_1_0 = mshr[1:0];
  assign w_2 = mem0[mshr_1_0];
  assign access_fire = (state_w & req_valid);
  assign mem1_access_widx_2 = req_addr[1:0];
  assign mem1_access_widx_2_w = mem0[mem1_access_widx_2];
  assign req_addr_5_2 = req_addr[5:2];
  assign w_3 = (mem1_access_widx_2_w[5:5] & (mem1_access_widx_2_w[3:0] == req_addr_5_2));
  assign mshr_next = (access_fire ? (w_3 ? mshr : req_addr) : mshr);
  assign mshr_data_next = (access_fire ? (w_3 ? mshr_data : req_data) : mshr_data);
  assign mshr_write_next = (access_fire ? (w_3 ? mshr_write : req_write) : mshr_write);
  assign state_after_access = (access_fire ? (w_3 ? state : 2'h1) : state);
  assign req_write_w = (w_3 & req_write);
  assign mem1_access_wen = (access_fire ? req_write_w : 1'h0);
  assign mem1_access_widx = mem1_access_widx_2;
  assign mem1_access_wdata = req_data;
  assign mem0_access_wen = (access_fire ? req_write_w : 1'h0);
  assign mem0_access_widx = mem1_access_widx_2;
  assign mem0_access_wdata = {2'h3, req_addr_5_2};
  assign writeBack_fire = (state_after_access == 2'h1);
  assign state_after_writeBack = (writeBack_fire ? 2'h2 : state_after_access);
  assign fill_fire = ((state_after_writeBack == 2'h2) & mem_rvalid);
  assign mem1_fill_wen = (fill_fire ? 1'h1 : 1'h0);
  assign mem1_fill_widx_2 = mshr_next[1:0];
  assign mem1_fill_widx = mem1_fill_widx_2;
  assign mem1_fill_wdata = (mshr_write_next ? mshr_data_next : mem_rdata);
  assign mem0_fill_wen = (fill_fire ? 1'h1 : 1'h0);
  assign mem0_fill_widx = mem1_fill_widx_2;
  assign mem0_fill_wdata = {1'h1, mshr_write_next, mshr_next[5:2]};
  assign state_next = (reset ? 2'h0 : (fill_fire ? 2'h0 : state_after_writeBack));
  assign req_ready = state_w;
  assign resp_valid = (((state_w & req_valid) & (w[5:5] & (w[3:0] == req_addr[5:2]))) & (~req_write));
  assign resp_data = mem1[req_addr_1_0];
  assign mem_wb = (state_w_2 & (w_2[5:5] & w_2[4:4]));
  assign mem_wdata = mem1[mshr_1_0];
  assign mem_fill = (state == 2'h2);
  assign mem_addr = (state_w_2 ? {w_2[3:0], mshr_1_0} : mshr);
  always_ff @(posedge clk) begin
    if (rst) begin
      state <= 2'h0;
    end else begin
      state <= state_next;
    end
    if (rst) begin
      mshr <= 6'h0;
    end else begin
      mshr <= mshr_next;
    end
    if (rst) begin
      mshr_data <= 8'h0;
    end else begin
      mshr_data <= mshr_data_next;
    end
    if (rst) begin
      mshr_write <= 1'h0;
    end else begin
      mshr_write <= mshr_write_next;
    end
    if (mem0_access_wen) begin
      mem0[mem0_access_widx] <= mem0_access_wdata;
    end
    if (mem0_fill_wen) begin
      mem0[mem0_fill_widx] <= mem0_fill_wdata;
    end
    if (mem1_access_wen) begin
      mem1[mem1_access_widx] <= mem1_access_wdata;
    end
    if (mem1_fill_wen) begin
      mem1[mem1_fill_widx] <= mem1_fill_wdata;
    end
  end
endmodule

module mkBlockingCache_rules (
  input wire clock,
  input wire reset,
  input wire req_valid,
  input wire req_write,
  input wire [5:0] req_addr,
  input wire [7:0] req_data,
  input wire mem_rvalid,
  input wire [7:0] mem_rdata,
  output wire req_ready,
  output wire resp_valid,
  output wire [7:0] resp_data,
  output wire mem_wb,
  output wire [7:0] mem_wdata,
  output wire mem_fill,
  output wire [5:0] mem_addr
);
  mkBlockingCache_rules_core core (
    .clk(clock),
    .rst(1'h0),
    .reset(reset),
    .req_valid(req_valid),
    .req_write(req_write),
    .req_addr(req_addr),
    .req_data(req_data),
    .mem_rvalid(mem_rvalid),
    .mem_rdata(mem_rdata),
    .req_ready(req_ready),
    .resp_valid(resp_valid),
    .resp_data(resp_data),
    .mem_wb(mem_wb),
    .mem_wdata(mem_wdata),
    .mem_fill(mem_fill),
    .mem_addr(mem_addr)
  );
endmodule
